// The three generated files, laid out from the tokens Style Dictionary built per mode.
import type { BuiltModes, BuiltToken } from './build.ts';
import { DART_TYPES } from './values.ts';

export const HEADER =
  'Generated by packages/tokens/scripts/build.ts from packages/tokens/src. Do not edit.';

/** The tokens of `mode` whose value differs from light, in order. */
function changed(light: BuiltToken[], mode: BuiltToken[]): BuiltToken[] {
  const base = new Map(light.map((t) => [t.path, t.value]));
  return mode.filter((t) => base.get(t.path) !== t.value);
}

const declarations = (tokens: BuiltToken[]) => tokens.map((t) => `  --${t.name}: ${t.value};`);

/** CSS custom properties: every token on :root, then only what a theme or a density changes. */
export function css(modes: BuiltModes): string {
  return [
    `/* ${HEADER} */`,
    ':root {',
    '  color-scheme: light;',
    ...declarations(modes.light),
    '}',
    '',
    "[data-theme='dark'] {",
    '  color-scheme: dark;',
    ...declarations(changed(modes.light, modes.dark)),
    '}',
    '',
    "[data-density='compact'] {",
    ...declarations(changed(modes.light, modes.compact)),
    '}',
    '',
  ].join('\n');
}

/**
 * Token path prefix → Tailwind v4 theme namespace. Colours are offered only from the semantic
 * and brand layers, so a utility can never name a primitive colour; shadows only by job
 * (`shadow.*`: `shadow-card`, `shadow-focus`), never the elevation steps; the other scales are
 * offered as they are. Tokens outside these groups (control sizes, insets, z-index, durations)
 * have no Tailwind namespace and are used as `var(--shifa-…)`.
 */
const THEME: { prefix: string; namespace: string; layers?: BuiltToken['layer'][] }[] = [
  { prefix: 'color.', namespace: 'color', layers: ['semantic', 'brand'] },
  { prefix: 'space.', namespace: 'spacing' },
  { prefix: 'radius.', namespace: 'radius' },
  { prefix: 'shape.radius.', namespace: 'radius' },
  { prefix: 'shadow.', namespace: 'shadow' },
  { prefix: 'font.family.', namespace: 'font' },
  { prefix: 'text.family.', namespace: 'font' },
  { prefix: 'font.size.', namespace: 'text' },
  { prefix: 'text.size.', namespace: 'text' },
  { prefix: 'font.weight.', namespace: 'font-weight' },
  { prefix: 'text.weight.', namespace: 'font-weight' },
  { prefix: 'font.line-height.', namespace: 'leading' },
  { prefix: 'text.leading.', namespace: 'leading' },
  { prefix: 'motion.easing.', namespace: 'ease' },
];

/** Namespaces whose Tailwind defaults are removed, so only token values exist. */
const RESET = ['color', 'radius', 'shadow', 'font', 'text', 'font-weight', 'leading', 'ease'];

function themeName(token: BuiltToken): string | null {
  const group = THEME.find((g) => token.path.startsWith(g.prefix));
  if (group === undefined) return null;
  if (group.layers !== undefined && !group.layers.includes(token.layer)) return null;
  const rest = token.path.slice(group.prefix.length).replaceAll('.', '-');
  return `--${group.namespace}-${rest}`;
}

/** A Tailwind v4 `@theme inline` block: theme names that point at the custom properties. */
export function tailwind(tokens: BuiltToken[]): string {
  const lines: string[] = [];
  const origin = new Map<string, string>();
  for (const token of tokens) {
    const name = themeName(token);
    if (name === null) continue;
    const clash = origin.get(name);
    if (clash !== undefined) {
      throw new Error(`${token.path} and ${clash} both map to the Tailwind name ${name}`);
    }
    origin.set(name, token.path);
    lines.push(`  ${name}: var(--${token.name});`);
  }
  return [
    `/* ${HEADER} */`,
    '/* Import after tailwindcss and tokens.css. */',
    '@theme inline {',
    ...RESET.map((namespace) => `  --${namespace}-*: initial;`),
    ...lines,
    '}',
    '',
  ].join('\n');
}

function dartClass(name: string, doc: string, tokens: BuiltToken[]): string[] {
  const constants = tokens.map((t) => {
    const type = DART_TYPES[t.type];
    if (type === undefined) throw new Error(`${t.path}: no Dart type for ${t.type}`);
    return `  static const ${type} ${t.name} = ${t.value};`;
  });
  return [`/// ${doc}`, `abstract final class ${name} {`, ...constants, '}', ''];
}

/**
 * Dart constants. Colours of the semantic, brand and component layers come twice, under the
 * same names, in `ShifaColorsLight` and `ShifaColorsDark` (primitive colours are left out:
 * widgets use meanings, not palette steps). Values that change with density come twice in the
 * density classes; everything else is in `ShifaTokens`.
 */
export function dart(modes: BuiltModes): string {
  const themed = (t: BuiltToken) => t.type === 'color' && t.layer !== 'primitive';
  const dense = new Set(changed(modes.light, modes.compact).map((t) => t.path));
  const shared = modes.light.filter((t) => t.type !== 'color' && !dense.has(t.path));
  return [
    `// ${HEADER}`,
    '// ignore_for_file: type=lint',
    "import 'dart:ui' show Color;",
    '',
    '/// One layer of an elevation shadow, in logical pixels.',
    'typedef ShifaShadowLayer = ({',
    '  Color color,',
    '  double dx,',
    '  double dy,',
    '  double blur,',
    '  double spread,',
    '});',
    '',
    ...dartClass('ShifaTokens', 'Values that are the same in every theme and density.', shared),
    ...dartClass(
      'ShifaDensityComfortable',
      'Sizes of the comfortable density (touch, 44 px targets).',
      modes.light.filter((t) => dense.has(t.path)),
    ),
    ...dartClass(
      'ShifaDensityCompact',
      'Sizes of the compact density (desktop data screens, 32 px rows).',
      modes.compact.filter((t) => dense.has(t.path)),
    ),
    ...dartClass('ShifaColorsLight', 'Colours of the light theme.', modes.light.filter(themed)),
    ...dartClass('ShifaColorsDark', 'Colours of the dark theme.', modes.dark.filter(themed)),
  ]
    .join('\n')
    .replace(/\n+$/, '\n');
}
